import{_ as t,c as a,o as s,a3 as o}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Time off requests","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/requests/index.md","filePath":"master/human-resources/time-off/requests/index.md","lastUpdated":1791902625000}'),r={name:"master/human-resources/time-off/requests/index.md"};function n(i,e,d,l,h,p){return s(),a("div",null,e[0]||(e[0]=[o(`<h1 id="time-off-requests" tabindex="-1">Time off requests <a class="header-anchor" href="#time-off-requests" aria-label="Permalink to &quot;Time off requests&quot;">​</a></h1><p>A time off request is how an employee asks for days away from work, such as a holiday or a sick day. The request names the leave type, the dates and, if needed, a short reason. A manager then approves or refuses it. Aureus keeps the balance up to date and shows approved and pending days on the calendars.</p><blockquote><p><strong>In simple words:</strong> You ask for days off, someone with access to Management says yes or no, and the status tells everyone the outcome.</p></blockquote><p>Menu: <code>Time Off → My Time</code>, <code>Time Off → Overview</code> and <code>Time Off → Management → Time off</code>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Set up the <a href="./../setup/time-off-types.html">time off types</a> first. If a type needs an allocation, the employee also needs an approved <a href="./../allocations/">allocation</a> for it.</p></div><h2 id="request-lifecycle" tabindex="-1">Request lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request lifecycle&quot;">​</a></h2><p>Every request moves through a short life. You create it, a manager decides, and the result stays on the record.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Employee saves request</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   To Approve</span></span>
<span class="line"><span>    ↓       ↓</span></span>
<span class="line"><span>Approved   Refused</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th><th>Who does what</th></tr></thead><tbody><tr><td><strong>To Approve</strong></td><td>The request is saved and waits for a decision.</td><td>The employee, or a manager in Management, creates it.</td></tr><tr><td><strong>Approved</strong></td><td>The days are granted.</td><td>A manager clicks <strong>Approve</strong> in the three-dot row menu of <code>Management → Time off</code>.</td></tr><tr><td><strong>Refused</strong></td><td>The days are not granted.</td><td>A manager clicks <strong>Refuse</strong> in the same menu.</td></tr></tbody></table><p>The list also shows a fourth label, <strong>Second Approval</strong>, as a status name. You do not need it for the steps in this guide.</p><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use it to</th></tr></thead><tbody><tr><td><a href="./request-time-off.html">Request time off</a></td><td>Fill in the form, understand the duration and see what Aureus checks when you save.</td></tr><tr><td><a href="./my-time.html">My Time</a></td><td>See your balances, the calendar and the Holidays panel, and start a request from a date.</td></tr><tr><td><a href="./manage-requests.html">Manage requests</a></td><td>Review the list, then approve or refuse requests.</td></tr><tr><td><a href="./overview-calendar.html">Overview calendar</a></td><td>See a full year of requests on one calendar.</td></tr></tbody></table><h2 id="running-example" tabindex="-1">Running example <a class="header-anchor" href="#running-example" aria-label="Permalink to &quot;Running example&quot;">​</a></h2><p>The guide follows the same people from page to page.</p><ul><li><strong>Sarah Mitchell</strong> asks for 3 days of <strong>Paid Time Off</strong> for a family function. A manager approves it.</li><li><strong>Priya Sharma</strong> asks for <strong>Paid Time Off</strong>, but she has no allocation yet, so Aureus denies it. After she gets an allocation, her request is accepted. Her <strong>Sick Time Off</strong> request, once she has an allocation for it, is refused by a manager.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../setup/time-off-types.html">Time off types</a></li><li><a href="./../allocations/">Allocations</a></li><li><a href="./../../employees/">Employees</a></li></ul>`,17)]))}const c=t(r,[["render",n]]);export{u as __pageData,c as default};
